func Contains[T comparable](s []T, v T) bool {
    for _, x := range s {
        if x == v { return true }
    }
    return false
}

// Constraint custom com union de tipos (Go 1.18+)
type Numeric interface {
    ~int | ~int32 | ~int64 | ~float32 | ~float64
}
func Sum[T Numeric](s []T) T {
    var total T
    for _, v := range s { total += v }
    return total
}

